{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 45,
      "verse": 2,
      "text_ar": "أُخْبِرَ أَنَّهُ بَعْدَ سِتَّةِ أَيَّامٍ جَاءَ مَوْتُ آدَمَ. وَلَمَّا أَدْرَكَ آدَمُ أَنَّ سَاعَةَ مَوْتِهِ قَدِ اقْتَرَبَتْ، قَالَ لِجَمِيعِ بَنِيهِ: «هَا أَنَا ذَا ابْنُ تِسْعِ مِئَةٍ وَثَلَاثِينَ سَنَةً، وَإِذَا مُتُّ،"
    },
    {
      "chapter": 45,
      "verse": 3,
      "text_ar": "فَادْفِنُونِي نَحْوَ شُرُوقِ الشَّمْسِ فِي حَقْلِ ذَلِكَ الْمَسْكَنِ». وَحَدَثَ لَمَّا أَتَمَّ كُلَّ كَلَامِهِ أَنَّهُ أَسْلَمَ الرُّوحَ. (ثُمَّ) أَظْلَمَتِ الشَّمْسُ وَالْقَمَرُ"
    },
    {
      "chapter": 46,
      "verse": 1,
      "text_ar": "وَالْكَوَاكِبُ لِسَبْعَةِ أَيَّامٍ، وَعَانَقَ شِيثُ فِي مَنَاحَتِهِ مِنْ فَوْقُ جَسَدَ أَبِيهِ، وَكَانَتْ حَوَّاءُ تَنْظُرُ إِلَى الْأَرْضِ مَعَ طَيِّ يَدَيْهَا عَلَى رَأْسِهَا، وَبَكَى جَمِيعُ أَوْلَادِهَا بُكَاءً مُرّاً. وَهَا, ظَهَرَ"
    },
    {
      "chapter": 46,
      "verse": 2,
      "text_ar": "الْمَلَاكُ مِيخَائِيلُ وَوَقَفَ عِنْدَ رَأْسِ آدَمَ وَقَالَ لِشِيثَ: «قُمْ عَنْ جَسَدِ"
    },
    {
      "chapter": 46,
      "verse": 3,
      "text_ar": "أَبِيكَ وَهَلُمَّ إِلَيَّ وَانْظُرْ مَا هُوَ قَضَاءُ الرَّبِّ الْإِلَهِ بِشَأْنِهِ. فَهُوَ مخلوقه، وَقَدْ رَحِمَهُ اللهُ». وَنَفَخَ جَمِيعُ الْمَلَائِكَةِ بِأَبْوَاقِهِمْ وَصَرَخُوا:"
    }
  ]
}
